import {groups,groupForMuscle,groupById,exercises,exerciseById,alternatives,equipmentLabels} from './data.js';
import {muscleStats,within,dayNumber,workSets} from './science.js';
import {esc,btn,empty,select,num,dateLabel,modal,chart} from './ui.js';
import {TODAY} from './store.js';
export function exercisesView(C){const f=C.ui.exerciseFilters||{},list=filterExercises(f);return `<div class="page-head"><div><div class="eyebrow">Learn the movement</div><h1>Exercise library</h1><p>${exercises.length} curated movements. Practical technique, shared anatomy.</p></div>${btn('Explore the atlas','go-anatomy')}</div><div class="filterbar"><input class="search" name="exercise-query" placeholder="Search names, aliases or muscles" value="${esc(f.query||'')}" aria-label="Search exercises">${filterSelect('muscle','All muscle groups',groups.map(g=>[g.id,g.name]),f.muscle)}${filterSelect('equipment','All equipment',Object.entries(equipmentLabels),f.equipment)}${filterSelect('pattern','All movement patterns',[...new Set(exercises.map(e=>e.pattern))].map(p=>[p,p.replaceAll('-',' ')]),f.pattern)}${filterSelect('difficulty','All levels',['beginner','intermediate','advanced'].map(s=>[s,s]),f.difficulty)}${filterSelect('objective','All objectives',[['strength','Strength'],['hypertrophy','Muscle growth'],['endurance','Endurance'],['mobility','Mobility'],['general','General fitness']],f.objective)}</div><div id="exercise-results">${exerciseResults(list)}</div><p class="footer-note">Muscle involvement is a qualitative anatomy-based classification. Primary, secondary and stabilizing roles depend on execution and do not measure activation or prove exercise superiority. Instructions are general coaching summaries, not an injury rehabilitation program.</p>`}
function filterSelect(key,label,options,value){return `<select data-exercise-filter="${key}" aria-label="${label}"><option value="">${label}</option>${options.map(([id,n])=>`<option value="${id}" ${value===id?'selected':''}>${esc(n)}</option>`).join('')}</select>`}
function filterExercises(f){return exercises.filter(e=>(!f.query||(e.name+' '+e.aliases.join(' ')+' '+[...e.primary,...e.secondary].map(g=>groupById(g)?.name).join(' ')).toLowerCase().includes(f.query.toLowerCase()))&&(!f.muscle||e.primary.includes(f.muscle)||e.secondary.includes(f.muscle))&&(!f.equipment||e.equipment.includes(f.equipment))&&(!f.pattern||e.pattern===f.pattern)&&(!f.difficulty||e.difficulty===f.difficulty)&&(!f.objective||e.objectives.includes(f.objective)))}
const exerciseResults=list=>`<p class="count">${list.length} movements</p>${list.length?`<div class="exercise-grid">${list.map(e=>`<button class="exercise-card" data-action="exercise:${e.id}"><div class="type">${e.pattern.replaceAll('-',' ')} · ${e.difficulty}</div><h3>${esc(e.name)}</h3><div class="pills">${e.primary.map(g=>`<span class="pill">${groupById(g)?.name}</span>`).join('')}</div><div class="meta">${e.equipment.map(id=>equipmentLabels[id]).join(' · ')}</div></button>`).join('')}</div>`:empty('No matching movements','Try fewer filters or a broader search.')}`;
export function exerciseDialog(C,id){const e=exerciseById(id);if(!e)return;const alts=alternatives(e,C.state.profile.equipment);const d=modal(e.name,`<div class="pills">${[e.pattern.replaceAll('-',' '),e.difficulty,e.unilateral?'Unilateral · log both sides':'Bilateral / whole movement'].map(x=>`<span class="pill secondary">${x}</span>`).join('')}</div><div class="subsection"><h3>Muscle involvement</h3>${[['Primary',e.primary],['Secondary',e.secondary],['Stabilizers',e.stabilizers]].map(([label,ids])=>`<p class="note-box"><strong>${label}:</strong> ${ids.map(g=>groupById(g)?.name).join(', ')||'Not assigned'}</p>`).join('')}<p class="meta">Group-level roles; no activation percentages or head-isolation claims. Cardio and mobility are not counted toward strength-set volume.</p></div><h3>Setup & execution</h3><ol class="detail-list">${e.instructions.map(i=>`<li>${esc(i)}</li>`).join('')}</ol><h3>Common errors</h3><ul class="detail-list">${e.errors.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><h3>Safety & range</h3><p class="note-box">${esc(e.safety)} ${esc(e.rom)}</p><p class="meta">Joints / motion: ${esc(e.joints.join(', '))}</p><h3>Equipment-aware alternatives</h3><p class="meta">Matches your equipment and a similar pattern or primary group; alternatives are not mechanically identical.</p>${alts.length?alts.map(a=>`<div class="row"><span>${esc(a.name)}</span>${btn('View','exercise:'+a.id,'small')}</div>`).join(''):empty('No matching alternative','Update available equipment in Settings or use library filters.')}<div class="button-group subsection">${btn('View muscles','atlas-exercise:'+id)}${btn('Add to workout','add-exercise-workout:'+id,'primary')}</div><p class="footer-note">Anatomical actions support these classifications; resistance-training guidance does not independently validate every technique detail. ${C.sourceLinks(e.sourceIds)}</p>`,()=>{});d.querySelector('.modal-footer').remove()}
export function anatomyView(C){const view=C.ui.atlasView||'front',overlay=C.ui.atlasOverlay||'identify',exercise=C.ui.atlasExercise||'bench-press',selected=C.ui.atlasMuscle||'pectoralis-major',all=allMuscles(C);return `<div class="page-head"><div><div class="eyebrow">Anatomy meets your training</div><h1>Muscle atlas</h1><p>Select a region. Understand its role. Follow your recorded work.</p></div>${btn('View analytics','go-insights')}</div><div class="anatomy-layout"><div><div class="card" style="padding:18px;margin-bottom:16px"><div class="tabs" role="group" aria-label="Anatomical view" style="margin-bottom:16px">${[['front','Front'],['back','Back'],['side','Lateral reference']].map(([id,label])=>`<button aria-pressed="${view===id}" class="${view===id?'active':''}" data-action="atlas-view:${id}">${label}</button>`).join('')}</div><div class="form-grid">${select('atlas-overlay','Overlay',overlay,[['identify','Identify muscles'],['exercise','Exercise involvement'],['volume','Working sets · 7 days'],['recent','Recent activity · 28 days'],['frequency','Training days · 7 days'],['recovery','Time since training · heuristic']])}${overlay==='exercise'?select('atlas-exercise','Exercise',exercise,exercises.map(e=>[e.id,e.name])):select('atlas-muscle','Select a muscle',selected,all.map(m=>[m.id,m.name]))}</div></div><div class="anatomy-stage" id="anatomy-stage" aria-label="Interactive anatomical illustration"><div class="anatomy-model" id="anatomy-model"></div><div class="anatomy-caption">${view==='side'?'Historical lateral plate · label landmarks only':'Drag to pan · select a muscle · use zoom controls'}</div><div class="anatomy-tools">${btn('−','atlas-zoom:-.2','small')}${btn('+','atlas-zoom:.2','small')}${btn('Reset','atlas-reset','small')}</div></div><div class="legend">${overlay==='exercise'?'<span><i class="swatch" style="background:#1755e8"></i>Primary group</span><span><i class="swatch" style="background:#85b7f8"></i>Secondary group</span>':overlay==='identify'?'<span><i class="swatch" style="background:#1755e8"></i>Selected region</span>':'<span><i class="swatch" style="background:#d1d8e4"></i>No recorded primary work</span><span><i class="swatch" style="background:#1755e8"></i>More primary work / more recent</span>'}</div><div class="button-group" style="margin-top:12px">${[['←','-30|0'],['↑','0|-30'],['↓','0|30'],['→','30|0']].map(([label,id])=>`<button class="btn small" data-action="atlas-pan:${id}" aria-label="Pan ${label==='←'?'left':label==='↑'?'up':label==='↓'?'down':'right'}">${label}</button>`).join('')}</div><p class="footer-note">Front/back: Ryan Graves, <a href="https://www.figma.com/community/file/1320468164820924031" target="_blank" rel="noopener">Human Anatomy Component System</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Geometry preserved; labels normalized and interactive highlights added. Lateral plate: Hermann Braus (1921), public domain, <a href="https://commons.wikimedia.org/wiki/File:Braus_1921_248.png" target="_blank" rel="noopener">via Wikimedia Commons</a>.</p></div><div class="stack"><section class="card" id="muscle-panel">${musclePanel(C,selected)}</section><section class="card"><h2>How to read this atlas</h2><p class="note-box">The illustrations show superficial regions, not every muscle. Missing deep-muscle shapes are not invented. The lateral plate is a historical, partly dissected reference with point labels, not a matching segmented side view.</p><p class="note-box">Exercise and volume overlays map to anatomical groups. Selecting a subregion shows its group's logged work; it does not prove that individual fibers received that dose. Numbered abdominal and lateral core slips are grouped rather than treated as separate muscles.</p><details class="chart-details"><summary>Methodology & limitations</summary><p>Each completed, non-warm-up strength set counts once for every primary group assigned to the exercise. Secondary sets are reported separately. Stabilizers are excluded. For unilateral movements, one logged set row represents a completed left/right pair. These are set exposures, not measured stimulus. Summing across groups double-counts shared sets.</p><p>Training-day frequency counts distinct calendar days. Time-since-training uses the last logged day and the chosen ${C.state.profile.recoveryHours||48}-hour window. It is a display heuristic; it does not measure biological recovery.</p><p>The source labels and boundaries are illustrative and not a clinically validated segmented atlas. Some upper lateral core slips may overlap serratus territory; their precise boundaries are not independently validated.</p></details></section></div></div>`}
function allMuscles(C){return [...new Map(Object.values(C.anatomyMap.views).flatMap(v=>v.muscles).map(m=>[m.muscleId,{id:m.muscleId,name:m.name}])).values()].sort((a,b)=>a.name.localeCompare(b.name))}
function matchingGroups(id){if(id==='deltoid')return groups.filter(g=>['front-delts','side-delts','rear-delts'].includes(g.id));if(id==='biceps-brachii')return [groupById('biceps')];const g=groupForMuscle(id);return g?[g]:[]}
function musclePanel(C,id){
 const m=allMuscles(C).find(m=>m.id===id)||C.side.landmarks.find(m=>m.muscleId===id),matched=matchingGroups(id),stats=muscleStats(C.state.sessions,exercises,groups,TODAY(),7),hist=muscleStats(C.state.sessions,exercises,groups,TODAY(),3650),relevant=exercises.filter(e=>matched.some(g=>e.primary.includes(g.id)||e.secondary.includes(g.id)));
 const sections=matched.map(g=>{const s=stats[g.id];return '<div class="subsection"><span class="pill">'+g.name+' · group-level analytics</span><p class="note-box" style="margin-top:14px">'+esc(g.action)+'</p><div class="row"><span>Primary working sets · 7 days</span><strong>'+s.primary+'</strong></div><div class="row"><span>Secondary sets · 7 days</span><strong>'+s.secondary+'</strong></div><div class="row"><span>Training days · 7 days</span><strong>'+s.frequency+'</strong></div><div class="row"><span>Latest recorded work</span><strong>'+(hist[g.id]?.last?dateLabel(hist[g.id].last):'None')+'</strong></div></div>'}).join('');
 const history=matched.flatMap(g=>hist[g.id].history.map(x=>({...x,group:g.name}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);
 return '<div class="eyebrow">Selected region</div><h2 style="font-size:1.6rem;margin:12px 0">'+esc(m?.name||id)+'</h2>'+(matched.length?sections:'<p class="note-box">This source region is identifiable, but the curated library has no validated group relationship assigned. No volume or exercise match is inferred.</p>')+(C.ui.atlasOverlay==='recovery'?'<p class="notice">Time since recorded training is a display heuristic. Timing alone cannot tell whether you are recovered; absence of records does not establish recovery.</p>':'')+'<h3 class="subsection">Related exercises</h3><p class="meta">Primary or secondary involvement at group level.</p>'+(relevant.length?relevant.slice(0,8).map(e=>'<div class="row"><div><strong>'+esc(e.name)+'</strong><p>'+(matched.some(g=>e.primary.includes(g.id))?'Primary':'Secondary')+' group · '+e.equipment.map(x=>equipmentLabels[x]).join(', ')+'</p></div>'+btn('View','exercise:'+e.id,'small')+'</div>').join(''):empty('No assigned exercise matches','This region remains available for anatomical identification.'))+'<h3 class="subsection">Recent group history</h3>'+(history.length?history.map(x=>'<div class="row"><div><strong>'+esc(exerciseById(x.exerciseId)?.name)+'</strong><p>'+dateLabel(x.date)+' · '+x.sets+' '+x.role+' sets · '+x.group+'</p></div>'+btn('Session','session:'+x.sessionId,'small')+'</div>').join(''):'<p class="meta">No associated sets recorded.</p>')+(matched.length?'<p class="footer-note">'+C.sourceLinks(matched.flatMap(g=>g.sourceIds))+'</p>':'')
}
export async function mountAtlas(C){if((location.hash.slice(1)||'overview')!=='anatomy')return;const model=document.querySelector('#anatomy-model'),view=C.ui.atlasView||'front';if(view==='side'){model.innerHTML=`<div class="anatomy-side"><img src="/assets/side-reference.png" alt="Historical lateral anatomical plate by Hermann Braus"><div>${C.side.landmarks.map((p,i)=>`<button class="pin" style="left:${p.x/C.side.width*100}%;top:${p.y/C.side.height*100}%" data-muscle="${p.muscleId}" title="${esc(p.name)}" aria-label="${esc(p.name)}">${i+1}</button>`).join('')}</div></div>`}else{model.innerHTML=C.svg[view];const svg=model.querySelector('svg');svg.removeAttribute('width');svg.removeAttribute('height');svg.setAttribute('role','group');svg.setAttribute('aria-label',view+' superficial musculature');for(const m of C.anatomyMap.views[view].muscles){const node=svg.querySelector('#'+m.pathId);if(!node)continue;node.dataset.muscle=m.muscleId;node.setAttribute('tabindex','0');node.setAttribute('role','button');node.setAttribute('aria-label',m.name+' · '+m.side);node.style.fill=colorFor(C,m.muscleId)}}for(const el of model.querySelectorAll('[data-muscle]')){el.addEventListener('click',()=>{if(C.ui.dragged)return;selectMuscle(C,el.dataset.muscle)});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectMuscle(C,el.dataset.muscle)}})}const stage=document.querySelector('#anatomy-stage');let pointer=null;stage.onpointerdown=e=>{if(e.target.closest('.anatomy-tools'))return;pointer={x:e.clientX,y:e.clientY,id:e.pointerId};C.ui.dragged=false};stage.onpointermove=e=>{if(!pointer)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.abs(dx)+Math.abs(dy)>3){C.ui.dragged=true;C.ui.panX=(C.ui.panX||0)+dx;C.ui.panY=(C.ui.panY||0)+dy;pointer.x=e.clientX;pointer.y=e.clientY;transform(C)}};stage.onpointerup=()=>{pointer=null;setTimeout(()=>C.ui.dragged=false,50)};stage.onpointerleave=()=>pointer=null;transform(C)}
function transform(C){const el=document.querySelector('#anatomy-model');if(el)el.style.transform=`translate(${C.ui.panX||0}px,${C.ui.panY||0}px) scale(${C.ui.zoom||1})`}
function colorFor(C,id){const g=groupForMuscle(id),overlay=C.ui.atlasOverlay||'identify',selected=C.ui.atlasMuscle||'pectoralis-major';if(overlay==='identify')return id===selected?'#1755e8':'#b9c5d8';if(!g)return '#d1d8e4';if(overlay==='exercise'){const e=exerciseById(C.ui.atlasExercise||'bench-press');return e.primary.includes(g.id)?'#1755e8':e.secondary.includes(g.id)?'#85b7f8':'#d1d8e4'}const stats=muscleStats(C.state.sessions,exercises,groups,TODAY(),overlay==='recent'||overlay==='recovery'?3650:7),s=stats[g.id];if(overlay==='volume')return tint(s.primary/12);if(overlay==='frequency')return tint(s.frequency/4);if(overlay==='recent')return s.last?tint(Math.max(0,1-(dayNumber(TODAY())-dayNumber(s.last))/28)):'#d1d8e4';if(overlay==='recovery')return s.last?tint(Math.max(0,1-(dayNumber(TODAY())-dayNumber(s.last))*24/(C.state.profile.recoveryHours||48))):'#d1d8e4';return '#d1d8e4'}
const tint=x=>{x=Math.max(0,Math.min(1,x));return `rgb(${Math.round(209+(23-209)*x)},${Math.round(216+(85-216)*x)},${Math.round(228+(232-228)*x)})`};
function selectMuscle(C,id){C.ui.atlasMuscle=id;document.querySelector('#muscle-panel').innerHTML=musclePanel(C,id);const select=document.querySelector('[name=atlas-muscle]');if(select)select.value=id;document.querySelectorAll('#anatomy-model [data-muscle]').forEach(n=>{if(n.tagName.toLowerCase()!=='button')n.style.fill=colorFor(C,n.dataset.muscle)})}
export async function anatomyAction(a,id,C){if(a==='exercise'){exerciseDialog(C,id);return true}if(a==='atlas-exercise'){C.ui.atlasExercise=id;C.ui.atlasOverlay='exercise';C.ui.atlasMuscle=groupById(exerciseById(id).primary[0])?.muscleIds[0]||'pectoralis-major';document.querySelector('#modal').close();location.hash='anatomy';C.render();return true}if(a==='atlas-view'){C.ui.atlasView=id;C.ui.zoom=1;C.ui.panX=0;C.ui.panY=0;C.render();return true}if(a==='atlas-zoom'){C.ui.zoom=Math.min(3,Math.max(.6,(C.ui.zoom||1)+Number(id)));transform(C);return true}if(a==='atlas-reset'){C.ui.zoom=1;C.ui.panX=0;C.ui.panY=0;transform(C);return true}if(a==='atlas-pan'){const [x,y]=id.split('|').map(Number);C.ui.panX=(C.ui.panX||0)+x;C.ui.panY=(C.ui.panY||0)+y;transform(C);return true}return false}
export function anatomyInput(e,C){const el=e.target;if(el.name==='exercise-query'||el.dataset.exerciseFilter){C.ui.exerciseFilters||={};C.ui.exerciseFilters[el.name==='exercise-query'?'query':el.dataset.exerciseFilter]=el.value;document.querySelector('#exercise-results').innerHTML=exerciseResults(filterExercises(C.ui.exerciseFilters));return true}if(el.name==='atlas-overlay'){C.ui.atlasOverlay=el.value;C.render();return true}if(el.name==='atlas-exercise'){C.ui.atlasExercise=el.value;C.render();return true}if(el.name==='atlas-muscle'){selectMuscle(C,el.value);return true}return false}
